package com.example.hotelreservation.config;
import com.example.hotelreservation.domain.reservation.client.*; import com.example.hotelreservation.domain.rate.dto.RateQuoteResponse; import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.client.*; import org.springframework.web.server.ResponseStatusException;
@Configuration public class ReservationClientConfig {
 @Bean GuestClient guestClient(RestClient.Builder b,@Value("${services.guest-url:http://localhost:8080}")String url){RestClient c=b.baseUrl(url).build();return id->{try{c.get().uri("/guests/{id}",id).retrieve().toBodilessEntity();}catch(RestClientException e){throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"Guest Service unavailable",e);}};}
 @Bean HotelClient hotelClient(RestClient.Builder b,@Value("${services.hotel-url:http://localhost:8080}")String url){RestClient c=b.baseUrl(url).build();return (h,t)->{try{c.get().uri("/hotels/{id}",h).retrieve().toBodilessEntity();}catch(RestClientException e){throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"Hotel Service unavailable",e);}};}
 @Bean RateClient rateClient(RestClient.Builder b,@Value("${services.rate-url:http://localhost:8080}")String url){RestClient c=b.baseUrl(url).build();return (h,in,out)->{try{return c.get().uri(u->u.path("/internal/hotels/{id}/rates/quote").queryParam("checkin",in).queryParam("checkout",out).build(h)).retrieve().body(RateQuoteResponse.class).getTotalRate();}catch(RestClientException|NullPointerException e){throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"Rate Service unavailable",e);}};}
}
